window.GameLoading={mount(){
 const root=document.createElement('section');root.className='api-loading';root.hidden=true;root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-labelledby','api-loading-heading');
 root.innerHTML='<div class="api-loading-panel"><div class="api-loading-top"><span>이딴게 무기?</span><span class="api-loading-time">00:00</span></div><h2 id="api-loading-heading">잠깐, 이걸로<br>싸울 수 있다고?</h2><div class="api-loading-art"><img alt="네가 그린 원본 낙서"></div><p class="api-loading-status" role="status" aria-live="polite"></p><ol class="api-loading-steps"><li>그림 읽기</li><li>무기 탄생</li><li>기술 도트</li><li>준비 완료</li></ol><div class="api-loading-skills"></div><p class="api-loading-count">그림의 가능성을 찾고 있어</p><div class="api-loading-actions"><button type="button" data-loading-action="view" disabled>무기 먼저 보기</button><button type="button" data-loading-action="retry" hidden>도트 다시 준비</button><button type="button" class="secondary" data-new-game>새 게임</button></div><p class="api-loading-tip">잘 그릴 필요 없어. 네가 그린 모양이 기술의 정체성이 돼.<br>네 기술의 전용 도트가 모두 준비되면 전투로 출발해.</p></div>';
 document.body.append(root);const find=s=>root.querySelector(s),heading=find('h2'),status=find('.api-loading-status'),count=find('.api-loading-count'),view=find('[data-loading-action="view"]'),retry=find('[data-loading-action="retry"]'),slots=[];let weapon=null,timer=null,started=0,atlasId='',epoch=0,previousFocus,onView=null,onBack=null,onRetry=null,battle=false;
 const back=document.createElement('button');back.type='button';back.dataset.loadingAction='back';back.textContent='공방에서 더 읽기';back.hidden=true;find('.api-loading-actions').append(back);back.addEventListener('click',()=>{hide();onBack?.();});
 for(let i=0;i<4;i++){const slot=document.createElement('div'),canvas=document.createElement('canvas'),name=document.createElement('strong'),note=document.createElement('small');slot.className='api-loading-slot';canvas.width=canvas.height=96;name.textContent='기술 '+(i+1);note.textContent='아직 비밀';slot.append(canvas,name,note);find('.api-loading-skills').append(slot);slots.push({slot,canvas,name,note});}
 const phase=index=>{root.querySelectorAll('.api-loading-steps li').forEach((li,i)=>{li.classList.toggle('current',i===index);li.classList.toggle('complete',i<index);});};
 const hide=()=>{if(!root.hidden)window.GameAudio?.loading(false);root.hidden=true;clearInterval(timer);timer=null;document.body.style.overflow='';previousFocus?.focus?.({preventScroll:true});};view.addEventListener('click',()=>{const action=onView;if(!battle)hide();onView=null;if(action)Promise.resolve().then(action).catch(error=>console.error(error));});retry.addEventListener('click',()=>{if(battle&&onRetry){root.dataset.error='false';retry.hidden=true;onRetry();}else{hide();document.getElementById('retry-effects')?.click();}});
 root.addEventListener('keydown',event=>{if(event.key==='Escape'&&(!back.hidden||!view.disabled)){event.preventDefault();hide();onBack?.();}if(event.key==='Tab'){const buttons=[...root.querySelectorAll('button')].filter(b=>!b.disabled&&!b.hidden),first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
 function begin(image,{currentWeapon=null}={}){battle=false;back.hidden=true;onBack=onRetry=null;if(root.hidden)window.GameAudio?.loading(true);epoch++;onView=null;previousFocus=document.activeElement;weapon=currentWeapon;atlasId='';root.dataset.error='false';root.hidden=false;document.body.style.overflow='hidden';find('img').src=image;heading.innerHTML='잠깐, 이걸로<br>싸울 수 있다고?';status.textContent='낙서에 숨은 가능성을 찾는 중';count.textContent='그림의 가능성을 찾고 있어';view.disabled=true;view.textContent='무기 먼저 보기';retry.hidden=true;slots.forEach((s,i)=>{s.slot.classList.remove('ready');s.name.textContent='기술 '+(i+1);s.note.textContent='아직 비밀';s.canvas.getContext('2d').clearRect(0,0,96,96);});phase(0);started=Date.now();clearInterval(timer);const tick=()=>{const seconds=Math.floor((Date.now()-started)/1000);find('.api-loading-time').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');};tick();timer=setInterval(tick,1000);find('[data-new-game]').focus({preventScroll:true});if(weapon)setWeapon(weapon);}
 async function update(message,current=weapon){if(message&&root.dataset.error!=='true')status.textContent=message;if(!current)return;weapon=current;const rows=current.effectAtlas?(current.effectAtlas.readyRows||[0,1,2,3]):[];count.textContent='기술 도트 '+rows.length+' / 4 완성';slots.forEach((s,i)=>{s.name.textContent=current.moves?.[i]?.name||'기술 '+(i+1);s.slot.style.setProperty('--skill-color',Craft.Types.color(current.moves?.[i]?.element||'normal'));s.note.textContent=rows.includes(i)?'완성':'준비 중';s.slot.classList.toggle('ready',rows.includes(i));});if(!current.effectAtlas||current.effectAtlas.id===atlasId)return;atlasId=current.effectAtlas.id;const token=epoch;try{for(const i of rows){const element=current.moves[i].element,atlas=await BattleSpriteAtlas.loadGenerated(atlasId,element,{allowFadeEmpty:current.effectAtlas.layout==='skill-2x2-v1',readyRows:rows});if(token!==epoch)return;const ctx=slots[i].canvas.getContext('2d');ctx.clearRect(0,0,96,96);BattleSpriteAtlas.drawFrame(ctx,atlas,i,1,48,48,86,{alpha:1});}}catch{if(token===epoch)atlasId='';}}
 function setWeapon(current){weapon=current;heading.textContent=current.name;status.textContent='무기와 기술이 탄생했어. 전용 도트에 움직임을 담을게.';phase(2);update('',current);}
 function playable(action){view.disabled=false;if(typeof action==='function')onView=action;}
 function done(current){weapon=current;root.dataset.error='false';if(battle)heading.textContent='전투 준비 완료!';else heading.innerHTML='이딴 것도<br>무기가 됐다!';status.textContent='네 기술의 도트까지 준비 완료!';phase(3);update('',current);view.disabled=false;view.textContent=battle?'전투 시작':'완성된 무기 보기';retry.hidden=true;clearInterval(timer);timer=null;}
 function fail(error,{canPlay=!!weapon}={}){root.dataset.error='true';status.textContent=error.message||String(error);view.disabled=battle;retry.hidden=!canPlay;view.textContent=battle?'도트를 다시 준비해 줘':canPlay?'완성된 무기 보기':'그림으로 돌아가기';clearInterval(timer);timer=null;}
 function beginBattle(current,actions){begin(current.artwork,{currentWeapon:current});battle=true;onView=actions.enter;onBack=actions.back;onRetry=actions.retry;back.hidden=false;heading.textContent='전투로 출발!';view.disabled=true;view.textContent='기술 도트 준비 중…';find('.api-loading-tip').textContent='네 기술의 전용 도트가 모두 완성되면 전투로 출발해. 공방으로 돌아가 기술을 더 읽어도 돼.';root.querySelectorAll('.api-loading-steps li').forEach((li,i)=>li.textContent=['무기 확인','기술 확인','기술 도트','전투 준비'][i]);back.focus({preventScroll:true});}
 return{begin,beginBattle,setWeapon,update,playable,done,fail,hide};
}};
